const payload=[['water_bucket',1],['spruce_boat',1],['sweet_berries',4]],records=[],collects=[];let c=null;function receiver(){const p=bot.players.p1?.entity?.position;return p&&Math.abs(p.x-6.5)<.45&&Math.abs(p.y-67)<.3&&p.z>81.05&&p.z<81.6;}const onC=(a,i)=>{if(a.id===bot.players.p1?.entity?.id)collects.push([i.getDroppedItem?.()?.name,i.getDroppedItem?.()?.count,i.id]);};bot.on('playerCollect',onC);try{if(!safeCamp()||!receiver())throw Error('P1_NOT_THRESHOLD');const p4=bot.players.p4?.entity?.position;if(p4&&p4.distanceTo(new Vec3(6.6,67,82.15))<1.55)throw Error('COMPETING_P4');for(const[n,amount]of payload){if(!receiver())throw Error('P1_MOVED_BETWEEN_ASSETS');await frontInside();c=await bot.openChest(bot.blockAt(new Vec3(7,67,82)));const stock=c.containerItems().filter(i=>i.name===n).reduce((a,i)=>a+i.count,0);if(stock<amount)throw Error('INSUFFICIENT_'+n);const before=count(n);await c.withdraw(bot.registry.itemsByName[n].id,null,amount);await c.close();c=null;if(!receiver()||count(n)!==before+amount)throw Error('RECEIVER_OR_WITHDRAW');await bot.lookAt(bot.players.p1.entity.position.offset(0,.7,0),true);await ticks(6);await bot.toss(bot.registry.itemsByName[n].id,null,amount);await asideInside();await ticks(45);const retained=count(n)-before;records.push({n,amount,stockBefore:stock,donorRetained:retained,collectEvidence:collects.filter(v=>v[0]===n)});if(retained>0)throw Error('DONOR_REPICK_'+n);}}
catch(e){issue=e.message;console.log('BUNDLE_ISSUE',issue);}finally{if(c)await c.close();try{c=await bot.openChest(bot.blockAt(new Vec3(7,67,82)));for(const[n]of payload){const qty=count(n);if(qty)await c.deposit(bot.registry.itemsByName[n].id,null,qty);}const finalStock=c.containerItems().map(i=>[i.name,i.count]);global.P3BundleFinal=finalStock;await c.close();c=null;}catch(e){console.log('BUNDLE_FINAL_FAIL',e.message);}if(c)await c.close();bot.removeListener('playerCollect',onC);cleanup();}return{issue,records,collects,bank:global.P3BundleFinal,hp:bot.health,food:bot.food,p:bot.entity.position,protectedEnd:safeCamp(),dead,lost};
